package aaa;

// nop instructions where a block starts: kotlinc begins a try with a nop.
// javac never emits nop, so the class is assembled by hand (generated by a
// small script; version 49, so it needs no StackMapTable):
//
//   static int f() {
//      0: nop                          ; the try starts here: [0,3) -> 3 Throwable
//      1: aconst_null  2: athrow
//      3: pop  4: bipush 7  6: ireturn
//   }
//   static int g(int x) {
//      0: iload_0  1: ifeq 7
//      4: iconst_5  5: istore_0
//      6: nop                          ; falls through into a branch target
//      7: iload_0  8: bipush 9  10: iadd  11: ireturn
//   }
//
// OpenLDK emitted nothing for a nop, so no block started at a try range
// that began with one, and f failed to compile.
public class nopstart extends ClassLoader
{
    private static final byte[] NOPS = new byte[] {
        -54,-2,-70,-66,0,0,0,49,0,12,1,0,17,97,97,97,47,110,111,112,115,116,97,114,116,36,78,111,112,115,7,0,1,1,0,16,106,97,118,97,47,108,97,110,103,47,79,98,106,101,99,116,7,0,3,1,0,19,106,97,118,97,47,108,97,110,103,47,84,104,114,111,119,97,98,108,101,7,0,5,1,0,4,67,111,100,101,1,0,1,102,1,0,3,40,41,73,1,0,1,103,1,0,4,40,73,41,73,0,33,0,2,0,4,0,0,0,0,0,2,0,9,0,8,0,9,0,1,0,7,0,0,0,27,0,1,0,0,0,0,0,7,0,1,-65,87,16,7,-84,0,1,0,0,0,3,0,3,0,6,0,0,0,9,0,10,0,11,0,1,0,7,0,0,0,24,0,2,0,1,0,0,0,12,26,-103,0,6,8,59,0,26,16,9,96,-84,0,0,0,0,0,0
    };

    protected Class<?> findClass(String name) throws ClassNotFoundException
    {
        if (!name.equals("aaa.nopstart$Nops")) throw new ClassNotFoundException(name);
        return defineClass(name, NOPS, 0, NOPS.length);
    }

    static Object call(Class<?> c, String name, Object... args)
    {
        try {
            Class<?>[] types = args.length == 0 ? new Class<?>[0] : new Class<?>[] { int.class };
            return c.getMethod(name, types).invoke(null, args);
        }
        catch (java.lang.reflect.InvocationTargetException e) { return "escaped: " + e.getCause(); }
        catch (Throwable t) { return "escaped: " + t; }
    }

    public static void main(String[] args) throws Exception
    {
        Class<?> c = new nopstart().loadClass("aaa.nopstart$Nops");
        String result = call(c, "f") + " " + call(c, "g", 0) + " " + call(c, "g", 1);
        System.out.println("7 9 14".equals(result) ? "OK" : "FAIL: " + result);
    }
}
